56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Dedicated audit logger recording every successful owner creation.
67	     */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
119	        if (hasReachedDailyRegistrationLimit()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        if (hasReachedCityOwnerLimit(owner.getCity())) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
129	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
130	        owner.setLocality(resolveLocality(owner.getCity()));
131	        owner.setCity(resolveCity(owner.getCity()));
132	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
133	        owner.setMembershipNumber(membershipNumber);
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
135	        owner.setMembershipTier(membershipNumber <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
136	        this.clinicService.saveOwner(owner);
137	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
138	            currentUsername(), owner.getId(), owner.getMembershipNumber());
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        this.clinicService.deleteOwner(owner);
170	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        HttpHeaders headers = new HttpHeaders();
181	        Pet pet = petMapper.toPet(petFieldsDto);
182	        owner.setId(ownerId);
183	        pet.setOwner(owner);
184	        pet.getType().setName(null);
185	        this.clinicService.savePet(pet);
186	        PetDto petDto = petMapper.toPetDto(pet);
187	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
188	            .buildAndExpand(pet.getId()).toUri());
189	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner != null) {
197	            Pet currentPet = this.clinicService.findPetById(petId);
198	            if (currentPet != null) {
199	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
200	                currentPet.setName(petFieldsDto.getName());
201	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
202	                this.clinicService.savePet(currentPet);
203	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	            }
205	        }
206	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
212	        HttpHeaders headers = new HttpHeaders();
213	        Visit visit = visitMapper.toVisit(visitFieldsDto);
214	        Pet pet = new Pet();
215	        pet.setId(petId);
216	        visit.setPet(pet);
217	        this.clinicService.saveVisit(visit);
218	        VisitDto visitDto = visitMapper.toVisitDto(visit);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
220	            .buildAndExpand(visit.getId()).toUri());
221	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
222	    }
223	
224	
225	    /**
226	     * Resolves the name of the currently authenticated user for audit logging, falling back to
227	     * {@code "anonymous"} when there is no authentication in the security context.
228	     *
229	     * @return the authenticated user name, never {@code null}
230	     */
231	    private static String currentUsername() {
232	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
233	        return authentication == null ? "anonymous" : authentication.getName();
234	    }
235	
236	    /**
237	     * The number of owners at the head of the registration sequence that receive the
238	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
239	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
240	     */
241	    private static final int MAX_FOUNDING_OWNERS = 100;
242	
243	    /**
244	     * The maximum number of owners that may be registered on any single calendar day.
245	     */
246	    private static final long MAX_DAILY_REGISTRATIONS = 20;
247	
248	    /**
249	     * Determines whether the daily owner-registration limit has already been reached. Owners are
250	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
251	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
252	     * owners may be created today.
253	     *
254	     * @return {@code true} if today's registration limit has been reached
255	     */
256	    private boolean hasReachedDailyRegistrationLimit() {
257	        LocalDate today = LocalDate.now();
258	        long registeredToday = this.clinicService.findAllOwners().stream()
259	            .filter(existing -> today.equals(existing.getRegistrationDate()))
260	            .count();
261	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
262	    }
263	
264	    /**
265	     * The maximum number of owners that may be registered in any single city.
266	     */
267	    private static final long MAX_OWNERS_PER_CITY = 8;
268	
269	    /**
270	     * Determines whether the given city has already reached its owner limit. Owners are matched to
271	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
272	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
273	     * no further owners may be created there.
274	     *
275	     * @param city the city of the new owner, may be {@code null}
276	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
277	     */
278	    private boolean hasReachedCityOwnerLimit(String city) {
279	        String normalized = normalize(city);
280	        long ownersInCity = this.clinicService.findAllOwners().stream()
281	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
282	            .count();
283	        return ownersInCity >= MAX_OWNERS_PER_CITY;
284	    }
285	
286	    /**
287	     * Builds the customer code for a newly created owner, formatted as
288	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
289	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
290	     *
291	     * @param city the city of the new owner
292	     * @return the assigned customer code
293	     */
294	    private String nextCustomerCode(String city) {
295	        long ownersInCity = this.clinicService.findAllOwners().stream()
296	            .filter(existing -> Objects.equals(
297	                normalize(existing.getCity()), normalize(city)))
298	            .count();
299	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
300	    }
301	
302	    /**
303	     * Resolves the city to store for a newly created owner. The city is title-cased (so
304	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
305	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
306	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
307	     * surrounding or repeated whitespace.
308	     *
309	     * @param city the city supplied for the new owner, may be {@code null}
310	     * @return the city to store, or {@code null} if the input was {@code null}
311	     */
312	    private String resolveCity(String city) {
313	        if (city == null) {
314	            return null;
315	        }
316	        String normalized = normalize(city);
317	        if (!normalized.isEmpty()) {
318	            for (Owner existing : this.clinicService.findAllOwners()) {
319	                if (normalized.equals(normalize(existing.getCity()))) {
320	                    return existing.getCity();
321	                }
322	            }
323	        }
324	        return toTitleCase(city);
325	    }
326	
327	    /**
328	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
329	     * and lower-casing the remaining letters, preserving the original whitespace. For example
330	     * {@code "new  YORK"} becomes {@code "New  York"}.
331	     *
332	     * @param value the raw value, never {@code null}
333	     * @return the title-cased value
334	     */
335	    private static String toTitleCase(String value) {
336	        StringBuilder result = new StringBuilder(value.length());
337	        boolean startOfWord = true;
338	        for (int i = 0; i < value.length(); i++) {
339	            char c = value.charAt(i);
340	            if (Character.isWhitespace(c)) {
341	                startOfWord = true;
342	                result.append(c);
343	            } else if (startOfWord) {
344	                result.append(Character.toTitleCase(c));
345	                startOfWord = false;
346	            } else {
347	                result.append(Character.toLowerCase(c));
348	            }
349	        }
350	        return result.toString();
351	    }
352	
353	    /**
354	     * Resolves the locality of a newly created owner relative to the owners present at the moment
355	     * it is created. The value is {@code "local"} when the new owner's city is the single most
356	     * common city among the existing owners, and {@code "remote"} otherwise. Cities are matched
357	     * using {@link #normalize(String)}, so the comparison ignores letter case and any surrounding
358	     * or repeated whitespace. When there are no existing owners, or when two or more cities tie for
359	     * the highest owner count, no city is the sole most common one and the result is
360	     * {@code "remote"}.
361	     *
362	     * @param city the city supplied for the new owner, may be {@code null}
363	     * @return {@code "local"} if the city is the single most common city, otherwise {@code "remote"}
364	     */
365	    private String resolveLocality(String city) {
366	        String normalized = normalize(city);
367	        Map<String, Long> ownersPerCity = this.clinicService.findAllOwners().stream()
368	            .map(existing -> normalize(existing.getCity()))
369	            .filter(normalizedCity -> !normalizedCity.isEmpty())
370	            .collect(Collectors.groupingBy(normalizedCity -> normalizedCity, Collectors.counting()));
371	        long highestCount = ownersPerCity.values().stream()
372	            .mapToLong(Long::longValue)
373	            .max()
374	            .orElse(0L);
375	        if (highestCount == 0L) {
376	            return "remote";
377	        }
378	        List<String> mostCommonCities = ownersPerCity.entrySet().stream()
379	            .filter(entry -> entry.getValue() == highestCount)
380	            .map(Map.Entry::getKey)
381	            .toList();
382	        boolean isSingleMostCommon = mostCommonCities.size() == 1
383	            && mostCommonCities.get(0).equals(normalized);
384	        return isSingleMostCommon ? "local" : "remote";
385	    }
386	
387	    /**
388	     * Counts how many existing owners share the given last name. Last names are matched using
389	     * {@link #normalize(String)}, so the count ignores letter case and any surrounding or repeated
390	     * whitespace. This is evaluated against the owners present at the moment the new owner is
391	     * created, before the new owner is persisted, so the new owner does not count itself.
392	     *
393	     * @param lastName the last name of the new owner, may be {@code null}
394	     * @return the number of existing owners sharing the same last name
395	     */
396	    private int countNamesakes(String lastName) {
397	        String normalized = normalize(lastName);
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> normalized.equals(normalize(existing.getLastName())))
400	            .count();
401	    }
402	
403	    /**
404	     * Determines whether the new owner shares a household with an existing owner, meaning another
405	     * owner already has the same address and city. Both the address and the city are matched using
406	     * {@link #normalize(String)}, so the comparison ignores letter case and any surrounding or
407	     * repeated whitespace. This is evaluated against the owners present at the moment the new owner
408	     * is created, before the new owner is persisted, so the new owner does not count itself.
409	     *
410	     * @param address the address of the new owner, may be {@code null}
411	     * @param city    the city of the new owner, may be {@code null}
412	     * @return {@code true} if an existing owner already has the same address and city
413	     */
414	    private boolean sharesHousehold(String address, String city) {
415	        String normalizedAddress = normalize(address);
416	        String normalizedCity = normalize(city);
417	        return this.clinicService.findAllOwners().stream()
418	            .anyMatch(existing -> normalizedAddress.equals(normalize(existing.getAddress()))
419	                && normalizedCity.equals(normalize(existing.getCity())));
420	    }
421	
422	    /**
423	     * Determines whether the given telephone number is already used by any other owner.
424	     *
425	     * @param owner the candidate owner
426	     * @return {@code true} if an owner with the same telephone number already exists in the data store
427	     */
428	    private boolean isDuplicateOwner(Owner owner) {
429	        return this.clinicService.findAllOwners().stream()
430	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
431	    }
432	
433	    /**
434	     * Determines whether the given email address is already used by any other owner. An owner
435	     * without an email address is never considered a duplicate on this criterion. Email addresses
436	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
437	     * surrounding or repeated whitespace.
438	     *
439	     * @param owner the candidate owner
440	     * @return {@code true} if the owner provides an email already used by an existing owner
441	     */
442	    private boolean isDuplicateEmail(Owner owner) {
443	        String email = normalize(owner.getEmail());
444	        if (email.isEmpty()) {
445	            return false;
446	        }
447	        return this.clinicService.findAllOwners().stream()
448	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
449	    }
450	
451	    /**
452	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
453	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
454	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
455	     * differently formatted representations of the same number are treated as duplicates. A
456	     * {@code null} value is returned unchanged.
457	     *
458	     * @param telephone the raw telephone number, may be {@code null}
459	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
460	     */
461	    private static String normalizeTelephone(String telephone) {
462	        if (telephone == null) {
463	            return null;
464	        }
465	        return telephone.replaceAll("[\\s()-]", "");
466	    }
467	
468	    /**
469	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
470	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
471	     * collapsed to a single space and the result is lower-cased. This is what makes
472	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
473	     * duplicates. A {@code null} value normalizes to the empty string.
474	     *
475	     * @param value the raw value, may be {@code null}
476	     * @return the normalized value, never {@code null}
477	     */
478	    private static String normalize(String value) {
479	        if (value == null) {
480	            return "";
481	        }
482	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
483	    }
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
488	        Owner owner = this.clinicService.findOwnerById(ownerId);
489	        if (owner != null) {
490	            Pet pet = owner.getPet(petId);
491	            if (pet != null) {
492	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
493	            }
494	        }
495	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	    }
497	}
